🐛 Bug
torch::nn::Linear without bias throws an error when to is called.
To Reproduce
#include<torch/torch.h>
int main(int argc, char* argv[])
{
  torch::Tensor x = torch::ones({100, 4});
  auto lopt       = torch::nn::LinearOptions(4, 4).bias(false);
  auto lin        = torch::nn::Linear(lopt);
  // works
  auto y          = lin->forward(x);
  // error
  lin->to(torch::kFloat64);
  x = torch::ones({100, 4}, torch::kFloat64);
  y = lin->forward(x);
}
